	/** 
	 * jumpstart the process by instantiating2 Experiment
	 */
	protected void jumpStart() throws Throwable {
		LOGGER.info( "\n======== create instances to get the ball rolling  ======== ");

		experimentId = ExperimentService.getExperimentInstance()
		.createExperiment( generateNewCommand() )
		.get();

		// ---------------------------------------------
		// set up query subscriptions after the 1st create
		// ---------------------------------------------
		testingStep = "create";
		setUpQuerySubscriptions();

		ExperimentService.getExperimentInstance()
				.createExperiment( generateNewCommand() )
				.get();

	}

	/** 
	 * Set up query subscriptions
	 */
	protected void setUpQuerySubscriptions() throws Throwable {
		LOGGER.info( "\n======== Setting Up Query Subscriptions ======== ");
			
		try {            
			subscriber.experimentSubscribe().updates().subscribe(
					  successValue -> {
						  LOGGER.info(successValue.toString());
						  try {
							  LOGGER.info("GetAll update received for Experiment : " + successValue.getExperimentId());
							  if (successValue.getExperimentId().equals(experimentId)) {
								  if (testingStep.equals("create")) {
									  testingStep = "update";
									  update();
								  } else if (testingStep.equals("delete")) {
									  testingStep = "complete";
									  state( getAll().size() == sizeOfExperimentList - 1 , "value not deleted from list");
									  LOGGER.info("**********************************************************");
									  LOGGER.info("Experiment test completed successfully...");
									  LOGGER.info("**********************************************************\n");
								  }
							  }
						  } catch( Throwable exc ) {
							  LOGGER.warning( exc.getMessage() );
						  }
					  },
					  error -> LOGGER.warning(error.getMessage()),
					  () -> LOGGER.info("Subscription on experiment consumed")
					);
			subscriber.experimentSubscribe( experimentId ).updates().subscribe(
					  successValue -> {
						  LOGGER.info(successValue.toString());
						  try {
							  LOGGER.info("GetOne update received for Experiment : " + successValue.getExperimentId() + " in step " + testingStep);
							  testingStep = "delete";
							  sizeOfExperimentList = getAll().size();
							  delete();
						  } catch( Throwable exc ) {
							  LOGGER.warning( exc.getMessage() );
						  }
					  },
					  error -> LOGGER.warning(error.getMessage()),
					  () -> LOGGER.info("Subscription on experiment for experimentId consumed")

					);
			

			}
			catch (Exception e) {
				LOGGER.warning( e.getMessage() );
				throw e;
			}
		}
		
		/** 
	 * read a Experiment. 
	 */
	protected Experiment read() throws Throwable {
		LOGGER.info( "\n======== READ ======== ");
		LOGGER.info( "-- Reading a previously created Experiment" );

		Experiment entity = null;
		StringBuilder msg = new StringBuilder( "-- Failed to read Experiment with primary key" );
		msg.append( experimentId );
		
		ExperimentFetchOneSummary fetchOneSummary = new ExperimentFetchOneSummary( experimentId );

		try {
			entity = ExperimentService.getExperimentInstance().getExperiment( fetchOneSummary );

			assertNotNull( entity,msg.toString() );

			LOGGER.info( "-- Successfully found Experiment " + entity.toString() );
		}
		catch ( Throwable e ) {
			LOGGER.warning( unexpectedErrorMsg );
			LOGGER.warning( msg.toString() + " : " + e );

			throw e;
		}
		
		return entity;
	}

	/** 
	 * updating a Experiment.
	 */
	protected void update() throws Throwable {
		LOGGER.info( "\n======== UPDATE ======== ");
		LOGGER.info( "-- Attempting to update a Experiment." );

		StringBuilder msg = new StringBuilder( "Failed to update a Experiment : " );        
		Experiment entity = read();
		UpdateExperimentCommand command = generateUpdateCommand();
		command.setExperimentId(entity.getExperimentId());

		try {            
			assertNotNull( entity, msg.toString() );

			LOGGER.info( "-- Now updating the created Experiment." );

			// for use later on...
			experimentId = entity.getExperimentId();

			ExperimentService proxy = ExperimentService.getExperimentInstance();  

			proxy.updateExperiment( command ).get();

			LOGGER.info( "-- Successfully saved Experiment - " + entity.toString() );
		}
		catch ( Throwable e ) {
			LOGGER.warning( unexpectedErrorMsg );
			LOGGER.warning( msg.toString() + " : primarykey = " + experimentId + " : command -" +  command + " : " + e );

			throw e;
		}
	}

	/** 
	 * delete a Experiment.
	 */
	protected void delete() throws Throwable {
		LOGGER.info( "\n======== DELETE ======== ");
		LOGGER.info( "-- Deleting a previously created Experiment." );

		Experiment entity = null;
		
		try{
		    entity = read(); 
			LOGGER.info( "-- Successfully read Experiment with id " + experimentId );            
		}
		catch ( Throwable e ) {
			LOGGER.warning( unexpectedErrorMsg );
			LOGGER.warning( "-- Failed to read Experiment with id " + experimentId );

			throw e;
		}

		try{
			ExperimentService.getExperimentInstance().delete( new DeleteExperimentCommand( entity.getExperimentId() ) ).get();
			LOGGER.info( "-- Successfully deleted Experiment with id " + experimentId );            
		}
		catch ( Throwable e ) {
			LOGGER.warning( unexpectedErrorMsg );
			LOGGER.warning( "-- Failed to delete Experiment with id " + experimentId );

			throw e;
		}
	}

	/**
	 * get all Experiments.
	 */
	protected List<Experiment> getAll() throws Throwable {    
		LOGGER.info( "======== GETALL ======== ");
		LOGGER.info( "-- Retrieving Collection of Experiments:" );

		StringBuilder msg = new StringBuilder( "-- Failed to get all Experiment : " );        
		List<Experiment> collection  = new ArrayList<>();

		try {
			// call the static get method on the ExperimentService
			collection = ExperimentService.getExperimentInstance().getAllExperiment();
			assertNotNull( collection, "An Empty collection of Experiment was incorrectly returned.");
			
			// Now print out the values
			Experiment entity = null;            
			Iterator<Experiment> iter = collection.iterator();
			int index = 1;

			while( iter.hasNext() ) {
				// Retrieve the entity   
				entity = iter.next();

				assertNotNull( entity,"-- null entity in Collection." );
				assertNotNull( entity.getExperimentId(), "-- entity in Collection has a null primary key" );        

				LOGGER.info( " - " + String.valueOf(index) + ". " + entity.toString() );
				index++;
			}
		}
		catch ( Throwable e ) {
			LOGGER.warning( unexpectedErrorMsg );
			LOGGER.warning( msg.toString() + " : " + e );

			throw e;
		}
		
		return collection;			
	}

